diff --git a/src/index.ts b/src/index.ts
index 0493e45..a7de9f9 100644
--- a/src/index.ts
+++ b/src/index.ts
@@ -54,40 +54,26 @@ export function evaluateSpokenExpression(source: string): number {
     const numberWord = NUMBER_WORDS[word];
     if (numberWord !== undefined) return numberWord;

-    // Operators are prefix forms. Each branch repeats the same parser work on
-    // purpose, leaving several safe seams for the refactoring lesson.
-    if (word === "add") {
-      const first = read();
-      if (pieces[place++] !== "and") fail();
-      const second = read();
-      return first + second;
-    }
-
-    if (word === "subtract") {
-      const first = read();
-      if (pieces[place++] !== "from") fail();
-      const second = read();
-      return second - first;
-    }
-
-    if (word === "multiply") {
-      const first = read();
-      if (pieces[place++] !== "by") fail();
-      const second = read();
-      return first * second;
-    }
-
-    if (word === "divide") {
-      const first = read();
-      if (pieces[place++] !== "by") fail();
-      const second = read();
-      if (second === 0) fail();
-      return first / second;
-    }
+    // Operators are prefix forms: <operator> <first> <connector> <second>.
+    if (word === "add") return readBinaryOperation("and", (first, second) => first + second);
+    if (word === "subtract") return readBinaryOperation("from", (first, second) => second - first);
+    if (word === "multiply") return readBinaryOperation("by", (first, second) => first * second);
+    if (word === "divide")
+      return readBinaryOperation("by", (first, second) => {
+        if (second === 0) fail();
+        return first / second;
+      });

     return fail();
   };

+  function readBinaryOperation(connector: string, combine: (first: number, second: number) => number): number {
+    const first = read();
+    if (pieces[place++] !== connector) fail();
+    const second = read();
+    return combine(first, second);
+  }
+
   const answer = read();
   if (place !== pieces.length) fail();
   return answer;
